def execute(plan: list[dict], budget: Budget) -> None:
    for step in plan:
        budget.consume(step)
        if not policy.allows(step, budget.spent):
            raise CircuitBreaker("blast radius exceeded")
        call_tool(step["tool"], step["args"])

